-- s93: тип документа-источника у цитат об ответственности (решение Сергея 05.10: только юридические документы печатаются)
alter table public.directory_facts add column if not exists source_kind text
  check (source_kind in ('terms','legal_notice','policy','inline_disclaimer','other'));
comment on column public.directory_facts.source_kind is 'Тип документа-источника у kind=responsibility: terms (T&C/ToS/EULA/AGB/MSA), legal_notice (legal notice/disclaimer page/impressum), policy (формальная политика с разделом об ответственности), inline_disclaimer (оговорка на странице продукта), other (блог/FAQ/маркетинг/пересказ закона). Печатаются только terms/legal_notice/policy — directoryModel.LEGAL_SOURCE_KINDS.';
