-- s93, следом (execute_sql): восемь цитат-обрывков, начинавшихся со строчной буквы, получили ведущее «…» (новая проверка импорта их поймала)
update public.directory_facts set quote = '…' || quote where id in (182,183,200,219,365,382,490,561) and quote not like '…%';
update public.directory_facts set quote = '…' || quote where id in (604,656,667,688,689,690,941,953,964,1075,1090,1263,1314,1326,1425,1538,1594,1779) and quote not like '…%';

